"""Independent approved D01/D02/D07/D13 arithmetic fixtures (private synthetic)."""

from decimal import Decimal, localcontext
from typing import Any

import pytest

from app.modules.physiology.realized_v2 import (
    LEGACY_MAPPING,
    correction_factor,
    estimate_realized,
    session_rpe_zone,
)

# All 25 expected values are literals, never generated by the tested formula.
FACTORS = (
    ("1.000", "1.125", "1.250", "1.250", "1.250"),
    ("0.875", "1.000", "1.125", "1.250", "1.250"),
    ("0.750", "0.875", "1.000", "1.125", "1.250"),
    ("0.625", "0.750", "0.875", "1.000", "1.125"),
    ("0.600", "0.625", "0.750", "0.875", "1.000"),
)
FULL_LOADS = (
    ("120", "135", "150", "150", "150"),
    ("105", "120", "135", "150", "150"),
    ("90", "105", "120", "135", "150"),
    ("75", "90", "105", "120", "135"),
    ("72", "75", "90", "105", "120"),
)
HALF_LOADS = (
    ("60", "67.5", "75", "75", "75"),
    ("52.5", "60", "67.5", "75", "75"),
    ("45", "52.5", "60", "67.5", "75"),
    ("37.5", "45", "52.5", "60", "67.5"),
    ("36", "37.5", "45", "52.5", "60"),
)


@pytest.mark.parametrize(
    "p,q,full,half",
    [
        (p, q, FULL_LOADS[p - 1][q - 1], HALF_LOADS[p - 1][q - 1])
        for p in range(1, 6)
        for q in range(1, 6)
    ],
)
def test_all_25_full_and_half_duration_results_for_both_scores(
    p: int,
    q: int,
    full: str,
    half: str,
) -> None:
    for score in (q * 2 - 1, q * 2):
        for actual, expected in (("120", full), ("60", half)):
            result = estimate_realized(
                planned_load=Decimal(120),
                planned_minutes=Decimal(120),
                actual_minutes=Decimal(actual),
                planned_zone=p,
                rpe=score,
            )
            assert result.value == Decimal(expected)


@pytest.mark.parametrize(
    "p,q,expected",
    [(p, q, FACTORS[p - 1][q - 1]) for p in range(1, 6) for q in range(1, 6)],
)
def test_all_25_factors(p: int, q: int, expected: str) -> None:
    assert correction_factor(p, q) == Decimal(expected)


@pytest.mark.parametrize(
    "rpe,zone",
    [(1, 1), (2, 1), (3, 2), (4, 2), (5, 3), (6, 3), (7, 4), (8, 4), (9, 5), (10, 5)],
)
def test_prospective_mapping(rpe: int, zone: int) -> None:
    assert session_rpe_zone(rpe).value == zone


def test_historical_mapping_and_unknown_version() -> None:
    assert session_rpe_zone(3, version=LEGACY_MAPPING).value == 1
    with pytest.raises(ValueError):
        session_rpe_zone(3, version="unknown")


@pytest.mark.parametrize(
    "p,t,a,z,r,expected",
    [
        ("120", "120", "60", 2, 3, "60"),  # owner A; new RPE3 = Z2
        ("100", "60", "90", 2, 1, "131.25"),  # owner B; uncapped overrun
        ("120", "120", "120", 4, 1, "75"),  # owner C; -3 is .625
        ("120", "120", "120", 2, 3, "120"),
        ("120", "120", "240", 1, 10, "300"),
        ("1", "3", "1", 1, 3, "0.375"),
        ("0.1", "3", "1", 1, 3, "0.0375"),
        ("0", "60", "30", 1, 1, "0"),
    ],
)
def test_duration_and_no_intermediate_rounding(
    p: str, t: str, a: str, z: int, r: int, expected: str
) -> None:
    result = estimate_realized(
        planned_load=Decimal(p),
        planned_minutes=Decimal(t),
        actual_minutes=Decimal(a),
        planned_zone=z,
        rpe=r,
    )
    assert result.value == Decimal(expected)
    assert "value=" not in repr(result)


def test_ambient_decimal_context_does_not_change_result() -> None:
    kwargs: dict[str, Any] = dict(
        planned_load=Decimal("1"),
        planned_minutes=Decimal("3"),
        actual_minutes=Decimal("1"),
        planned_zone=2,
        rpe=3,
    )
    expected = estimate_realized(**kwargs)
    with localcontext() as context:
        context.prec = 4
        assert estimate_realized(**kwargs) == expected
    assert len(expected.duration_ratio.as_tuple().digits) == 50


@pytest.mark.parametrize("rpe", [0, 11, -1, True, "3", 3.0, None, Decimal("NaN")])
def test_invalid_rpe(rpe: int) -> None:
    with pytest.raises(ValueError):
        session_rpe_zone(rpe)


@pytest.mark.parametrize(
    "value", [Decimal("-1"), Decimal("NaN"), Decimal("Infinity"), None, 1.0]
)
@pytest.mark.parametrize("key", ["planned_load", "planned_minutes", "actual_minutes"])
def test_invalid_numeric_input(key: str, value: Decimal) -> None:
    inputs: dict[str, Any] = dict(
        planned_load=Decimal("100"),
        planned_minutes=Decimal("60"),
        actual_minutes=Decimal("60"),
    )
    inputs[key] = value
    with pytest.raises(ValueError):
        estimate_realized(**inputs, planned_zone=2, rpe=3)


@pytest.mark.parametrize("key", ["planned_minutes", "actual_minutes"])
def test_zero_duration_is_not_completed_work(key: str) -> None:
    inputs: dict[str, Any] = dict(
        planned_load=Decimal("100"),
        planned_minutes=Decimal("60"),
        actual_minutes=Decimal("60"),
    )
    inputs[key] = Decimal(0)
    with pytest.raises(ValueError):
        estimate_realized(**inputs, planned_zone=2, rpe=3)
